<div class="d-flex justify-content-between mb-3"><h1 class="h3">Customers</h1><a class="btn btn-primary" href="<?= site_url('customers/new') ?>">+ Add Customer</a></div><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Name</th><th>Email</th><th>Phone</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($customers as $c): ?><tr><td class="fw-semibold"><?= esc($c['full_name']) ?></td><td><?= esc($c['email']) ?></td><td><?= esc($c['phone']?:'—') ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="<?= site_url('customers/'.$c['id'].'/edit') ?>">Edit</a><?= form_open('customers/'.$c['id'],['class'=>'d-inline','onsubmit'=>"return confirm('Delete this customer?')"]) ?><input type="hidden" name="_method" value="DELETE"><button class="btn btn-sm btn-outline-danger">Delete</button><?= form_close() ?></td></tr><?php endforeach ?><?php if(!$customers): ?><tr><td colspan="4" class="text-center text-secondary py-4">No customers yet.</td></tr><?php endif ?></tbody></table></div></div>
